#include <cstdio>
#include <bitset>
using namespace std;

typedef unsigned long long ULL;
#define next nxttt
#define prev prv
typedef bitset<128> u128;
const long long MOD = 1000000007;

u128 zero;

long long mod_pow(long long base, long long exp) {
    long long result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

inline int bit(int n) {
    return 1 << n;
}

inline u128 bitu128(int n) {
    u128 p = zero;
    p[n] = 1;
    return p;
}

const int maxN = 7;
const int max2N = 1 << maxN;
const int maxM = 100;
const int maxS = 64184;

const int sizes[maxN + 1] = {0, 5, 11, 37, 137, 821, 7529, 164184};
int len;
u128 bfs[maxS];

int SZ;
u128 what[maxS];
int ind[maxS];

int get_index(u128 state) {
    int pos = 0;
    for (int i = 0; i < 128; i++) {
        pos = (pos * 2 + state[i]) % SZ;
    }
    while (true) {
        if (what[pos] == state) {
            break;
        }
        if (what[pos] == 0) {
            what[pos] = state;
            bfs[len] = state;
            ind[pos] = len;
            ++len;
            return len - 1;
        }
        ++pos;
        if (pos == SZ) pos = 0;
    }
    return ind[pos];
}

int next_states[max2N][maxS];
int match[maxS];

void prepare(int n) {
    int N = bit(n);
    u128 fixed_size[maxN + 1] = {0};
    for (int mask = 0; mask < N; ++mask) {
        int cnt = 0;
        for (int i = 0; i < n; ++i) {
            if (mask & bit(i)) cnt++;
        }
        fixed_size[cnt] |= bitu128(mask);
    }
    SZ = sizes[n];
    for (int k = 0; k < SZ; ++k) {
        what[k] = 0;
    }
    len = 0;
    get_index(1);
    for (int k = 0; k < len; ++k) {
        u128 state = bfs[k];
        u128 pred_hall[maxN] = {0};
        for (int mask = 0; mask < N; ++mask) {
            if ((state & bitu128(mask)).any()) {
                for (int i = 0; i < n; ++i) {
                    pred_hall[i] |= bitu128(mask | bit(i));
                }
            }
        }
        for (int mask = 0; mask < N; ++mask) {
            u128 nxt = state;
            for (int i = 0; i < n; ++i) {
                if (mask & bit(i)) {
                    nxt |= pred_hall[i];
                }
            }
            next_states[mask][k] = get_index(nxt);
        }
        for (int i = n; i >= 0; --i) {
            if ((state & fixed_size[i]).any()) {
                match[k] = i;
                break;
            }
        }
    }
}

long long p[maxN][maxM];
long long prev[maxS];
long long cur[maxS];

long long compute(int n, int m) {
    prev[0] = 1;
    for (int k = 1; k < len; ++k) {
        prev[k] = 0;
    }
    int N = bit(n);
    for (int j = 0; j < m; ++j) {
        for (int k = 0; k < len; ++k) {
            cur[k] = 0;
        }
        for (int mask = 0; mask < N; ++mask) {
            long long prob = 1;
            for (int i = 0; i < n; ++i) {
                prob = (prob * (mask & bit(i) ? p[i][j] : (MOD + 1 - p[i][j]) % MOD)) % MOD;
            }
            for (int k = 0; k < len; ++k) {
                cur[next_states[mask][k]] = (cur[next_states[mask][k]] + prob * prev[k]) % MOD;
            }
        }
        for (int k = 0; k < len; ++k) {
            prev[k] = cur[k];
        }
    }
    long long answer = 0;
    for (int k = 0; k < len; ++k) {
        if (match[k] == n) answer = (answer + prev[k]) % MOD;
    }
    return answer;
}

int main() {
    int n, m;
    scanf("%d", &n);
    m = n;
    prepare(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            scanf("%lld", &p[i][j]);
            p[i][j] = p[i][j] * mod_pow(100, MOD - 2) % MOD;
        }
    }
    printf("%lld\n", compute(n, m));
    return 0;
}
